public class AVADocuRefSearch_Derived extends AVATCVDocuRefSearch_Derived { #localmacro.AVA_NDX select noFetch * from docuRef order by AVASortDesc desc where docuRef.refCompanyId == common.dataAreaId && docuRef.refTableId == common.tableId && docuRef.refRecId == common.recId && (docuRef.typeId == docuTypeId || !docuTypeId) && docuRef.restriction == restriction #endmacro
#localmacro.AVA_NDXquerySortByCreatedDateTime select noFetch * from docuRef order by AVASortDesc desc, CreatedDateTime asc where docuRef.refCompanyId == common.dataAreaId && docuRef.refTableId == common.tableId && docuRef.refRecId == common.recId && (docuRef.typeId == docuTypeId || ! docuTypeId ) && docuRef.restriction == restriction #endmacro
}

