/// <summary>
///
/// </summary>
protected void search()
{
    #localmacro.querySortByIndex
        select noFetch * from docuRef
            order by AVASortDesc desc
            where docuRef.refCompanyId  == common.dataAreaId    &&
                  docuRef.refTableId    == common.tableId       &&
                  docuRef.refRecId      == common.recId         &&
                  (docuRef.typeId        == docuTypeId  ||
                   ! docuTypeId
                  )
    #endmacro

    #localmacro.querySortByCreatedDateTime
        select noFetch * from docuRef
            order by AVASortDesc desc, CreatedDateTime asc
            where docuRef.refCompanyId  == common.dataAreaId    &&
                  docuRef.refTableId    == common.tableId       &&
                  docuRef.refRecId      == common.recId         &&
                  (docuRef.typeId        == docuTypeId  ||
                   !docuTypeId
                  )
    #endmacro

    if (sortByMostRecent)
    {
        if (allRestrictions)
            #querySortByCreatedDateTime;
        else
        {
            if (allPaperTypes && noSpecificPosition)
            {
                #querySortByCreatedDateTime &&
                docuRef.Restriction == restriction;
            }
            if (!allPaperTypes && noSpecificPosition)
            {
                switch (paperType)
                {
                    case AVATCVPaperType::Quotation :
                        #AVA_NDXquerySortByCreatedDateTime && docuRef.KCS_TCVPrintOnQuotation;
                        break;
                    case AVATCVPaperType::Confirm :
                        #AVA_NDXquerySortByCreatedDateTime && docuRef.KCS_TCVPrintOnConfirm;
                        break;
                    case AVATCVPaperType::PickingList :
                        #AVA_NDXquerySortByCreatedDateTime && docuRef.KCS_TCVPrintOnPickingList;
                        break;
                    case AVATCVPaperType::PackingSlip :
                        #AVA_NDXquerySortByCreatedDateTime && docuRef.KCS_TCVPrintOnPackingSlip;
                        break;
                    case AVATCVPaperType::Invoice :
                        #AVA_NDXquerySortByCreatedDateTime && docuRef.KCS_TCVPrintOnInvoice;
                        break;
                    case AVATCVPaperType::ProjInvoice :
                        #AVA_NDXquerySortByCreatedDateTime && docuRef.KCS_TCVPrintOnProjectInvoice;
                        break;
                    case AVATCVPaperType::PurchaseOrder :
                        #AVA_NDXquerySortByCreatedDateTime && docuRef.KCS_TCVPrintOnPurchaseOrder;
                        break;
                    case AVATCVPaperType::Work :
                        #AVA_NDXquerySortByCreatedDateTime && docuRef.KCS_TCVPrintOnWork;
                        break;
                    case AVATCVPaperType::PurchaseAgreement :
                        #AVA_NDXquerySortByCreatedDateTime && docuRef.AVATCVPrintOnPurchaseAgreement;
                        break;
                    case AVATCVPaperType::PurchaseRequisition :
                        #AVA_NDXquerySortByCreatedDateTime && docuRef.AVATCVPrintOnPurchaseRequisition;
                        break;
                    default :
                        #AVA_NDXquerySortByCreatedDateTime;
                        break;
                }
            }
            if (allPaperTypes && !noSpecificPosition)
            {
                #AVA_NDXquerySortByCreatedDateTime && docuRef.KCS_TCVNotePosition == notePosition;
            }
            if (!allPaperTypes && !noSpecificPosition)
            {
                switch (paperType)
                {
                    case AVATCVPaperType::Quotation :
                        #AVA_NDXquerySortByCreatedDateTime && docuRef.KCS_TCVPrintOnQuotation && docuRef.KCS_TCVNotePosition == notePosition;
                        break;
                    case AVATCVPaperType::Confirm :
                        #AVA_NDXquerySortByCreatedDateTime && docuRef.KCS_TCVPrintOnConfirm && docuRef.KCS_TCVNotePosition == notePosition;
                        break;
                    case AVATCVPaperType::PickingList :
                        #AVA_NDXquerySortByCreatedDateTime && docuRef.KCS_TCVPrintOnPickingList && docuRef.KCS_TCVNotePosition == notePosition;
                        break;
                    case AVATCVPaperType::PackingSlip :
                        #AVA_NDXquerySortByCreatedDateTime && docuRef.KCS_TCVPrintOnPackingSlip && docuRef.KCS_TCVNotePosition == notePosition;
                        break;
                    case AVATCVPaperType::Invoice :
                        #AVA_NDXquerySortByCreatedDateTime && docuRef.KCS_TCVPrintOnInvoice == NoYes::Yes && docuRef.KCS_TCVNotePosition == notePosition;
                        break;
                    case AVATCVPaperType::ProjInvoice :
                        #AVA_NDXquerySortByCreatedDateTime && docuRef.KCS_TCVPrintOnProjectInvoice == NoYes::Yes && docuRef.KCS_TCVNotePosition == notePosition;
                        break;
                    case AVATCVPaperType::PurchaseOrder :
                        #AVA_NDXquerySortByCreatedDateTime && docuRef.KCS_TCVPrintOnPurchaseOrder == NoYes::Yes && docuRef.KCS_TCVNotePosition == notePosition;
                        break;
                    case AVATCVPaperType::Work :
                        #AVA_NDXquerySortByCreatedDateTime && docuRef.KCS_TCVPrintOnWork == NoYes::Yes && docuRef.KCS_TCVNotePosition == notePosition;
                        break;
                    case AVATCVPaperType::PurchaseAgreement :
                        #AVA_NDXquerySortByCreatedDateTime && docuRef.AVATCVPrintOnPurchaseAgreement == NoYes::Yes && docuRef.KCS_TCVNotePosition == notePosition;
                        break;
                    case AVATCVPaperType::PurchaseRequisition :
                        #AVA_NDXquerySortByCreatedDateTime && docuRef.AVATCVPrintOnPurchaseRequisition == NoYes::Yes && docuRef.KCS_TCVNotePosition == notePosition;
                        break;
                    default :
                        #AVA_NDXquerySortByCreatedDateTime;
                        break;
                }
            }

        }
    }
    else
    {
        if (allRestrictions)
            #querySortByIndex;
        else
        {
            if (allPaperTypes && noSpecificPosition)
            {
                #querySortByIndex &&
                docuRef.Restriction == restriction;
            }
            if (!allPaperTypes && noSpecificPosition)
            {
                switch (paperType)
                {
                    case AVATCVPaperType::Quotation :
                        #AVA_NDX && docuRef.KCS_TCVPrintOnQuotation;
                        break;
                    case AVATCVPaperType::Confirm :
                        #AVA_NDX && docuRef.KCS_TCVPrintOnConfirm;
                        break;
                    case AVATCVPaperType::PickingList :
                        #AVA_NDX && docuRef.KCS_TCVPrintOnPickingList;
                        break;
                    case AVATCVPaperType::PackingSlip :
                        #AVA_NDX && docuRef.KCS_TCVPrintOnPackingSlip;
                        break;
                    case AVATCVPaperType::Invoice :
                        #AVA_NDX && docuRef.KCS_TCVPrintOnInvoice;
                        break;
                    case AVATCVPaperType::ProjInvoice :
                        #AVA_NDX && docuRef.KCS_TCVPrintOnProjectInvoice;
                        break;
                    case AVATCVPaperType::PurchaseOrder :
                        #AVA_NDX && docuRef.KCS_TCVPrintOnPurchaseOrder;
                        break;
                    case AVATCVPaperType::Work :
                        #AVA_NDX && docuRef.KCS_TCVPrintOnWork;
                        break;
                    case AVATCVPaperType::PurchaseAgreement :
                        #AVA_NDX && docuRef.AVATCVPrintOnPurchaseAgreement;
                        break;
                    case AVATCVPaperType::PurchaseRequisition :
                        #AVA_NDX && docuRef.AVATCVPrintOnPurchaseRequisition;
                        break;
                    default :
                        #AVA_NDX;
                        break;
                }
            }
            if (allPaperTypes && !noSpecificPosition)
            {
                #AVA_NDX && docuRef.KCS_TCVNotePosition == notePosition;
            }
            if (!allPaperTypes && !noSpecificPosition)
            {
                switch (paperType)
                {
                    case AVATCVPaperType::Quotation :
                        #AVA_NDX && docuRef.KCS_TCVPrintOnQuotation && docuRef.KCS_TCVNotePosition == notePosition;
                        break;
                    case AVATCVPaperType::Confirm :
                        #AVA_NDX && docuRef.KCS_TCVPrintOnConfirm && docuRef.KCS_TCVNotePosition == notePosition;
                        break;
                    case AVATCVPaperType::PickingList :
                        #AVA_NDX && docuRef.KCS_TCVPrintOnPickingList && docuRef.KCS_TCVNotePosition == notePosition;
                        break;
                    case AVATCVPaperType::PackingSlip :
                        #AVA_NDX && docuRef.KCS_TCVPrintOnPackingSlip && docuRef.KCS_TCVNotePosition == notePosition;
                        break;
                    case AVATCVPaperType::Invoice :
                        #AVA_NDX && docuRef.KCS_TCVPrintOnInvoice == NoYes::Yes && docuRef.KCS_TCVNotePosition == notePosition;
                        break;
                    case AVATCVPaperType::ProjInvoice :
                        #AVA_NDX && docuRef.KCS_TCVPrintOnProjectInvoice == NoYes::Yes && docuRef.KCS_TCVNotePosition == notePosition;
                        break;
                    case AVATCVPaperType::PurchaseOrder :
                        #AVA_NDX && docuRef.KCS_TCVPrintOnPurchaseOrder == NoYes::Yes && docuRef.KCS_TCVNotePosition == notePosition;
                        break;
                    case AVATCVPaperType::Work :
                        #AVA_NDX && docuRef.KCS_TCVPrintOnWork == NoYes::Yes && docuRef.KCS_TCVNotePosition == notePosition;
                        break;
                    case AVATCVPaperType::PurchaseAgreement :
                        #AVA_NDX && docuRef.AVATCVPrintOnPurchaseAgreement == NoYes::Yes && docuRef.KCS_TCVNotePosition == notePosition;
                        break;
                    case AVATCVPaperType::PurchaseRequisition :
                        #AVA_NDX && docuRef.AVATCVPrintOnPurchaseRequisition == NoYes::Yes && docuRef.KCS_TCVNotePosition == notePosition;
                        break;
                    default :
                        #AVA_NDX;
                        break;
                }
            }
        }
    }
}

